failure_threshold: float = 1.0
warning_threshold: float = 0.5
observe_until: str | None = None  # "YYYY-MM-DD"
soft_fail_until: str | None = None  # "YYYY-MM-DD"

def __post_init__(self) -> None:
    if self.failure_threshold < self.warning_threshold:
        raise ValueError(
            "failure_threshold must be >= warning_threshold: "
            f"{self.failure_threshold} < {self.warning_threshold}"
        )

def get_effective_stage(self, failure_rate: float) -> EnforcementStage:
    """Resolve the effective enforcement stage for the observed failure rate."""
    if failure_rate >= self.failure_threshold:
        return EnforcementStage.HARD_FAIL
    if failure_rate >= self.warning_threshold:
        return EnforcementStage.SOFT_FAIL
    return EnforcementStage.OBSERVE

def _filter_string_items(items: list[object]) -> list[str]:
    """Filter list to non-empty stripped strings."""
    return [a.strip() for a in items if isinstance(a, str) and a.strip()]

def _build_composite_output_ext(
    *,
    sample: Mapping[str, object],
    partition_count: int | None,
    schema_validation: CompositeSchemaValidationMetadata,
) -> CompositeOutputExt:
    """Build ``CompositeOutputExt`` from normalized sample payload."""
    common: dict[str, object] = {
        "composite_run_id": _normalize_optional_str(sample.get("_composite_run_id")),
        "source_providers": parse_composite_list(sample.get("_source_providers")),
        "enrichment_status": parse_composite_status(sample.get("_enrichment_status")),
        "lineage_created_at": parse_lineage_created_at(
            sample.get("_lineage_created_at")
        ),
        "schema_validation": schema_validation,
    }
    if partition_count is None:
        return CompositeOutputExt(**common)  # type: ignore[arg-type]
    return CompositeOutputExt(partition_count=partition_count, **common)  # type: ignore[arg-type]

@staticmethod
def _build_group_key(
    record: JsonDict, group_by_fields: list[str]
) -> tuple[str, ...]:
    return tuple(
        f"{type(record[field]).__name__}:{record[field]!r}"
        if field in record
        else "\x00MISSING"
        for field in group_by_fields
    )

def _parse_literal(value: object) -> object | None:
    """Parse a JSON literal from string payload with ast.literal_eval fallback."""
    if not isinstance(value, str):
        return None
    try:
        return cast("object", json.loads(value))
    except ValueError:
        # Fallback for legacy metadata using Python literals (single quotes)
        try:
            return cast("object", ast.literal_eval(value))
        except (ValueError, TypeError, SyntaxError, MemoryError, RecursionError):
            return None

def build_filter_strategy(
    *,
    include: set[CellularityType] | None,
    exclude: set[CellularityType] | None,
    keep_unresolved: bool,
) -> CellularityFilterStrategy:
    """Build filter strategy for include/exclude/unresolved policy.

    Precedence: include > exclude > pass-all.

    Args:
        include: If provided, only records with cellularity in this set are kept.
        exclude: If provided, records with cellularity in this set are removed.
        keep_unresolved: Whether records with unknown cellularity are retained.

    Returns:
        Callable CellularityFilterStrategy that accepts a CellularityType or None
        and returns True if the record should be kept.
    """
    if include:
        return _include_strategy(include, keep_unresolved)
    if exclude:
        return _exclude_strategy(exclude, keep_unresolved)
    return _pass_all_strategy(keep_unresolved)
